\n   * @returns\r\n   */\r\n  static bidiAwareTokenizer(text: string): TextTokenizer.ITextTokenizerSpan[] {\r\n    // For pure ASCII text, use the simple tokenizer\r\n    if (this.containsOnlyASCII(text)) {\r\n      return this.defaultTokenizer(text);\r\n    }\r\n\r\n    // For text without RTL characters, use default tokenizer\r\n    if (!this.containsRTL(text)) {\r\n      return this.defaultTokenizer(text);\r\n    }\r\n\r\n    // Check if it's mixed directional content\r\n    const isMixed = this.isMixedDirectional(text);\r\n    if (isMixed && this._getBidiTokenizer) {\r\n      // For mixed content, use bidi tokenizer\r\n      const bidiTokenizer = this._getBidiTokenizer();\r\n\r\n      // Add this null check:\r\n      if (typeof bidiTokenizer === \"function\") {\r\n        return bidiTokenizer(text);\r\n      } else {\r\n        console.warn(\r\n          \"Bidi tokenizer is not properly initialized, falling back to advanced RTL tokenizer\"\r\n        );\r\n        return this.advancedRTLTokenizer(text);\r\n      }\r\n    } else {\r\n      // For pure RTL, use the existing advancedRTLTokenizer\r\n      return this.advancedRTLTokenizer(text);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Advanced tokenizer for RTL text with punctuation separation\r\n   * @param text\r\n   * @returns\r\n   */\r\n  static advancedRTLTokenizer(\r\n    text: string\r\n  ): TextTokenizer.ITextTokenizerSpan[] {\r\n    // Check if it's mixed content - if so, use bidi tokenizer\r\n    if (this.isMixedDirectional(text) && this._getBidiTokenizer) {\r\n      const bidiTokenizer = this._getBidiTokenizer();\r\n      return bidiTokenizer(text);\r\n    }\r\n\r\n    // For pure RTL text, use the original logic\r\n    const hasRTL =\r\n      /[\\u0600-\\u06FF\\u0750-\\u077F\\u08A0-\\u08FF\\uFB50-\\uFDFF\\uFE70-\\uFEFF]/.test(\r\n        text\r\n      );\r\n\r\n    const words: string[] = [];\r\n    const len = text.length;\r\n    let startIndex = 0;\r\n    let i = 0;\r\n\r\n    for (; i < len; i++) {\r\n      const c = text.charAt(i);\r\n      if (c === \" \" || c === \"\\u200B\") {\r\n        if (i - startIndex > 0) {\r\n          const word = text.substring(startIndex, i);\r\n\r\n          // For RTL text, separate punctuation marks\r\n          if (hasRTL) {\r\n            const separatedTokens = TextTokenizer.separateRTLPunctuation(word);\r\n\r\n            words.push(...separatedTokens);\r\n          } else {\r\n            words.push(word);\r\n          }\r\n        }\r\n        startIndex = i + 1;\r\n        if (c === \" \") {\r\n          words.push(\" \");\r\n        }\r\n      }\r\n    }\r\n\r\n    if (i - startIndex > 0) {\r\n      const word = text.substring(startIndex, len);\r\n\r\n      // Handle final word with punctuation\r\n      if (hasRTL) {\r\n        const separatedTokens = TextTokenizer.separateRTLPunctuation(word);\r\n        words.push(...separatedTokens);\r\n      } else {\r\n        words.push(word);\r\n      }\r\n    }\r\n\r\n    return [\r\n      {\r\n        tokens: words,\r\n        rtl: hasRTL,\r\n      },\r\n    ];\r\n  }\r\n\r\n  /**\r\n   * Separate punctuation marks from words for proper RTL handling\r\n   */\r\n  static separateRTLPunctuation(word: string): string[] {\r\n    const punctuationRegex = /[.,،:;!?؟()\"\"\"«»\\-]/g;\r\n    const result: string[] = [];\r\n    let lastIndex = 0;\r\n    let match;\r\n\r\n    while ((match = punctuationRegex.exec(word)) !== null) {\r\n      // Add text before punctuation\r\n      if (match.index > lastIndex) {\r\n        result.push(word.substring(lastIndex, match.index));\r\n      }\r\n\r\n      // Add the punctuation mark as separate token\r\n      result.push(match[0]);\r\n      lastIndex = match.index + 1;\r\n    }\r\n\r\n    // Add remaining text after last punctuation\r\n    if (lastIndex < word.length) {\r\n      result.push(word.substring(lastIndex));\r\n    }\r\n\r\n    // If no punctuation found, return the original word\r\n    return result.length > 0\r\n      ? result.filter((token) => token.length > 0)\r\n      : [word];\r\n  }\r\n}\r\n\r\nexport default TextTokenizer;","/*\r\n * If not stated otherwise in this file or this component's LICENSE file the\r\n * following copyright and licenses apply:\r\n *\r\n * Copyright 2020 Metrological\r\n *\r\n * Licensed under the Apache License, Version 2.0 (the License);\r\n * you may not use this file except in compliance with the License.\r\n * You may obtain a copy of the License at\r\n *\r\n * http://www.apache.org/licenses/LICENSE-2.0\r\n *\r\n * Unless required by applicable law or agreed to in writing, software\r\n * distributed under the License is distributed on an \"AS IS\" BASIS,\r\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\r\n * See the License for the specific language governing permissions and\r\n * limitations under the License.\r\n */\r\n\r\nimport type {\r\n  ILineInfo,\r\n  ILineWord,\r\n  ISuffixInfo,\r\n} from \"./TextTextureRendererTypes.js\";\r\nimport TextTokenizer from \"./TextTokenizer.js\";\r\n\r\n/**\r\n * Returns CSS font setting string for use in canvas context.\r\n *\r\n * @param fontFace\r\n * @param fontStyle\r\n * @param fontSize\r\n * @param precision\r\n * @param defaultFontFace\r\n * @returns\r\n */\r\nexport function getFontSetting(\r\n  fontFace: string | (string | null)[] | null,\r\n  fontStyle: string,\r\n  fontSize: number,\r\n  precision: number,\r\n  defaultFontFace: string\r\n): string {\r\n  let ff = fontFace;\r\n\r\n  if (!Array.isArray(ff)) {\r\n    ff = [ff];\r\n  }\r\n\r\n  let ffs = [];\r\n  for (let i = 0, n = ff.length; i < n; i++) {\r\n    let curFf = ff[i];\r\n    // Replace the default font face `null` with the actual default font face set\r\n    // on the stage.\r\n    if (curFf == null) {\r\n      curFf = defaultFontFace;\r\n    }\r\n    if (curFf.indexOf(\" \") < 0) {\r\n      ffs.push(curFf);\r\n    } else {\r\n      ffs.push(`\"${curFf}\"`);\r\n    }\r\n  }\r\n\r\n  return `${fontStyle} ${fontSize * precision}px ${ffs.join(\",\")}`;\r\n}\r\n\r\n/**\r\n * Wrap a single line of text\r\n */\r\nexport function wrapText(\r\n  context: CanvasRenderingContext2D,\r\n  text: string,\r\n  wrapWidth: number,\r\n  letterSpacing: number,\r\n  textIndent: number,\r\n  maxLines: number,\r\n  suffix: string,\r\n  wordBreak: boolean\r\n): ILineInfo[] {\r\n  // Check if we need to use bidi tokenizer\r\n  const needsBidi = TextTokenizer.isMixedDirectional(text);\r\n  const rtl = TextTokenizer.getStartingDirection(text) == \"rtl\";\r\n\r\n  // Get appropriate tokenizer\r\n  const tokenize = needsBidi\r\n    ? (text: string) => TextTokenizer.bidiAwareTokenizer(text)\r\n    : TextTokenizer.getTokenizer();\r\n\r\n  const spans = tokenize(text);\r\n  const spaceWidth = measureText(context, \" \", letterSpacing);\r\n  const resultLines: ILineInfo[] = [];\r\n  let result = \"\";\r\n  let spaceLeft = wrapWidth - textIndent;\r\n  let totalWidth = textIndent;\r\n  let overflow = false;\r\n\r\n  // Process all spans\r\n  for (const span of spans) {\r\n    const words = span.tokens;\r\n\r\n    for (let j = 0; j < words.length; j++) {\r\n      // overflow?\r\n      if (maxLines && resultLines.length >= maxLines) {\r\n        overflow = true;\r\n        break;\r\n      }\r\n\r\n      const word = words[j]!;\r\n      const wordWidth =\r\n        word === \" \" ? spaceWidth : measureText(context, word, letterSpacing);\r\n\r\n      if (wordWidth > spaceLeft) {\r\n        // last word of last line overflows\r\n        if (maxLines && resultLines.length >= maxLines - 1) {\r\n          result += word;\r\n          totalWidth += wordWidth;\r\n          overflow = true;\r\n          break;\r\n        }\r\n\r\n        // commit line\r\n        if (result.length > 0) {\r\n          resultLines.push({\r\n            text: result,\r\n            width: totalWidth,\r\n          });\r\n          result = \"\";\r\n        }\r\n\r\n        // move word to next line, but drop a trailing space\r\n        if (word === \" \") {\r\n          totalWidth = textIndent;\r\n          spaceLeft = wrapWidth - textIndent;\r\n          continue;\r\n        }\r\n\r\n        // if word is too long, break it (caution: it could produce more than maxLines)\r\n        if (wordBreak && wordWidth > wrapWidth) {\r\n          const broken = breakWord(context, word, wrapWidth, letterSpacing);\r\n          let last = broken.pop()!;\r\n          for (const k of broken) {\r\n            resultLines.push({\r\n              text: k.text,\r\n              width: k.width,\r\n            });\r\n          }\r\n          result = last.text;\r\n          totalWidth = last.width;\r\n          spaceLeft = wrapWidth - last.width;\r\n        } else {\r\n          result = word;\r\n          totalWidth = wordWidth;\r\n          spaceLeft = wrapWidth - wordWidth;\r\n        }\r\n      } else {\r\n        spaceLeft -= wordWidth;\r\n        totalWidth += wordWidth;\r\n        result += word;\r\n      }\r\n    }\r\n\r\n    if (overflow) break;\r\n  }\r\n\r\n  // prevent exceeding maxLines\r\n  if (maxLines > 0 && resultLines.length >= maxLines) {\r\n    resultLines.length = maxLines;\r\n  }\r\n\r\n  // shorten and append ellipsis, if any\r\n  if (overflow && result.length > 0) {\r\n    const suffixWidth = suffix\r\n      ? measureText(context, suffix, letterSpacing)\r\n      : 0;\r\n\r\n    while (totalWidth + suffixWidth > wrapWidth && result.length > 0) {\r\n      result = result.substring(0, result.length - 1);\r\n      totalWidth = measureText(context, result, letterSpacing);\r\n    }\r\n\r\n    if (suffix) {\r\n      while (result.endsWith(\" \")) {\r\n        result = result.substring(0, result.length - 1);\r\n        totalWidth -= spaceWidth;\r\n      }\r\n      if (rtl) result = suffix + result;\r\n      else result += suffix;\r\n      totalWidth += suffixWidth;\r\n    }\r\n  }\r\n\r\n  if (result.length > 0) {\r\n    resultLines.push({\r\n      text: result,\r\n      width: totalWidth,\r\n    });\r\n  }\r\n\r\n  return resultLines;\r\n}\r\n\r\n/**\r\n * add punctuation positioning for RTL text\r\n * Note: This is now handled by the bidi tokenizer\r\n */\r\nexport function addRTLPunctuation(text: string): string {\r\n  const words = text.split(\" \");\r\n  const fixedWords = words.map((word) => {\r\n    const punctuationRegex = /([.,،:;!?؟()\"\"\"«»\\-]+)$/;\r\n    const match = word.match(punctuationRegex);\r\n\r\n    if (match) {\r\n      const punctuation = match[0];\r\n      const wordWithoutPunctuation = word.replace(punctuationRegex, \"\");\r\n      return punctuation + wordWithoutPunctuation;\r\n    }\r\n\r\n    return word;\r\n  });\r\n\r\n  return fixedWords.join(\" \");\r\n}\r\n\r\n/**\r\n * Determine how to handle overflow, and what suffix (e.g. ellipsis) to render\r\n */\r\nexport function getSuffix(\r\n  maxLinesSuffix: string,\r\n  textOverflow: string | null,\r\n  wordWrap: boolean\r\n): ISuffixInfo {\r\n  if (wordWrap) {\r\n    return {\r\n      suffix: maxLinesSuffix,\r\n      nowrap: false,\r\n    };\r\n  }\r\n\r\n  if (!textOverflow) {\r\n    return {\r\n      suffix: \"\",\r\n      nowrap: false,\r\n    };\r\n  }\r\n\r\n  switch (textOverflow) {\r\n    case \"clip\":\r\n      return {\r\n        suffix: \"\",\r\n        nowrap: true,\r\n      };\r\n    case \"ellipsis\":\r\n      return {\r\n        suffix: maxLinesSuffix,\r\n        nowrap: true,\r\n      };\r\n    default:\r\n      return {\r\n        suffix: textOverflow || maxLinesSuffix,\r\n        nowrap: true,\r\n      };\r\n  }\r\n}\r\n\r\n/**\r\n * Measure the width of a string accounting for letter spacing.\r\n *\r\n * @param context\r\n * @param word\r\n * @param space\r\n */\r\nexport function measureText(\r\n  context: CanvasRenderingContext2D,\r\n  word: string,\r\n  space: number = 0\r\n): number {\r\n  const { width } = context.measureText(word);\r\n  return space > 0 ? width + word.length * space : width;\r\n}\r\n\r\n/**\r\n * Break a word into smaller parts if it exceeds the maximum width.\r\n *\r\n * @param context\r\n * @param word\r\n * @param wordWrapWidth\r\n * @param space\r\n */\r\nexport function breakWord(\r\n  context: CanvasRenderingContext2D,\r\n  word: string,\r\n  wordWrapWidth: number,\r\n  space: number = 0\r\n): ILineWord[] {\r\n  const result: ILineWord[] = [];\r\n  let token = \"\";\r\n  let prevWidth = 0;\r\n  // parts of the word fitting exactly wordWrapWidth\r\n  for (let i = 0; i < word.length; i++) {\r\n    const c = word.charAt(i);\r\n    token += c;\r\n    const width = measureText(context, token, space);\r\n    if (width > wordWrapWidth) {\r\n      result.push({\r\n        text: token.substring(0, token.length - 1),\r\n        width: prevWidth,\r\n      });\r\n      token = c;\r\n      prevWidth = measureText(context, token, space);\r\n    } else {\r\n      prevWidth = width;\r\n    }\r\n  }\r\n  // remaining text\r\n  if (token.length > 0) {\r\n    result.push({\r\n      text: token,\r\n      width: prevWidth,\r\n    });\r\n  }\r\n  return result;\r\n}\r\n","/*\r\n * If not stated otherwise in this file or this component's LICENSE file the\r\n * following copyright and licenses apply:\r\n *\r\n * Copyright 2020 Metrological\r\n *\r\n * Licensed under the Apache License, Version 2.0 (the License);\r\n * you may not use this file except in compliance with the License.\r\n * You may obtain a copy of the License at\r\n *\r\n * http://www.apache.org/licenses/LICENSE-2.0\r\n *\r\n * Unless required by applicable law or agreed to in writing, software\r\n * distributed under the License is distributed on an \"AS IS\" BASIS,\r\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\r\n * See the License for the specific language governing permissions and\r\n * limitations under the License.\r\n */\r\n\r\nimport StageUtils from \"../tree/StageUtils.mjs\";\r\nimport type Stage from \"../tree/Stage.mjs\";\r\nimport type TextTexture from \"./TextTexture.mjs\";\r\nimport type {\r\n  IRenderInfo,\r\n  ILinesInfo,\r\n  ILineInfo,\r\n  IDrawLineInfo,\r\n} from \"./TextTextureRendererTypes.js\";\r\nimport {\r\n  getFontSetting,\r\n  getSuffix,\r\n  measureText,\r\n  wrapText,\r\n} from \"./TextTextureRendererUtils.js\";\r\n\r\nexport default class TextTextureRenderer {\r\n  protected _stage: Stage;\r\n  protected _canvas: HTMLCanvasElement;\r\n  protected _context: CanvasRenderingContext2D;\r\n  protected _settings: Required<TextTexture.Settings>;\r\n  protected prevShadowSettings: [string, number, number, number] | null = null;\r\n  public renderInfo: IRenderInfo | undefined;\r\n\r\n  constructor(\r\n    stage: Stage,\r\n    canvas: HTMLCanvasElement,\r\n    settings: Required<TextTexture.Settings>\r\n  ) {\r\n    this._stage = stage;\r\n    this._canvas = canvas;\r\n    this._context = this._canvas.getContext(\"2d\")!;\r\n    this._settings = settings;\r\n  }\r\n\r\n  setFontProperties() {\r\n    this._context.font = getFontSetting(\r\n      this._settings.fontFace,\r\n      this._settings.fontStyle,\r\n      this._settings.fontSize,\r\n      this._stage.getRenderPrecision(),\r\n      this._stage.getOption(\"defaultFontFace\")\r\n    );\r\n    this._context.textBaseline = this._settings.textBaseline;\r\n  }\r\n\r\n  _load() {\r\n    if (/*Utils.isWeb &&*/ document.fonts) {\r\n      const fontSetting = getFontSetting(\r\n        this._settings.fontFace,\r\n        this._settings.fontStyle,\r\n        this._settings.fontSize,\r\n        this._stage.getRenderPrecision(),\r\n        this._stage.getOption(\"defaultFontFace\")\r\n      );\r\n      try {\r\n        if (!document.fonts.check(fontSetting, this._settings.text)) {\r\n          // Use a promise that waits for loading.\r\n          return document.fonts\r\n            .load(fontSetting, this._settings.text)\r\n            .catch((err) => {\r\n              // Just load the fallback font.\r\n              console.warn(\"[Lightning] Font load error\", err, fontSetting);\r\n            })\r\n            .then(() => {\r\n              if (!document.fonts.check(fontSetting, this._settings.text)) {\r\n                console.warn(\"[Lightning] Font not found\", fontSetting);\r\n              }\r\n            });\r\n        }\r\n      } catch (e) {\r\n        console.warn(\"[Lightning] Can't check font loading for \" + fontSetting);\r\n      }\r\n    }\r\n    return Promise.resolve();\r\n  }\r\n\r\n  draw() {\r\n    // We do not use a promise so that loading is performed syncronous when possible.\r\n    const loadPromise = this._load();\r\n    if (!loadPromise) {\r\n      return /*Utils.isSpark ? this._stage.platform.drawText(this) :*/ this._draw();\r\n    } else {\r\n      return loadPromise.then(() => {\r\n        return /*Utils.isSpark ? this._stage.platform.drawText(this) :*/ this._draw();\r\n      });\r\n    }\r\n  }\r\n\r\n  _calculateRenderInfo(): IRenderInfo {\r\n    const renderInfo: Partial<IRenderInfo> = {};\r\n\r\n    const precision = this._stage.getRenderPrecision();\r\n    const paddingLeft = this._settings.paddingLeft * precision;\r\n    const paddingRight = this._settings.paddingRight * precision;\r\n    const fontSize = this._settings.fontSize * precision;\r\n    let offsetY =\r\n      this._settings.offsetY === null\r\n        ? null\r\n        : this._settings.offsetY * precision;\r\n    let lineHeight = (this._settings.lineHeight || fontSize) * precision;\r\n    const w = this._settings.w * precision;\r\n    const h = this._settings.h * precision;\r\n    let wordWrapWidth = this._settings.wordWrapWidth * precision;\r\n    const cutSx = this._settings.cutSx * precision;\r\n    const cutEx = this._settings.cutEx * precision;\r\n    const cutSy = this._settings.cutSy * precision;\r\n    const cutEy = this._settings.cutEy * precision;\r\n    const letterSpacing = (this._settings.letterSpacing || 0) * precision;\r\n    const textIndent = this._settings.textIndent * precision;\r\n    const text = this._settings.text;\r\n    const maxLines = this._settings.maxLines;\r\n\r\n    