e for the specific language governing permissions and\r\n * limitations under the License.\r\n */\r\n\r\nimport NoiseTexture from \"../../../textures/NoiseTexture.mjs\";\r\nimport DefaultShader from \"./DefaultShader.mjs\";\r\n\r\n/**\r\n * This shader can be used to fix a problem that is known as 'gradient banding'.\r\n */\r\nexport default class DitheringShader extends DefaultShader {\r\n\r\n    constructor(ctx) {\r\n        super(ctx);\r\n\r\n        this._noiseTexture = new NoiseTexture(ctx.stage);\r\n\r\n        this._graining = 1/256;\r\n\r\n        this._random = false;\r\n    }\r\n\r\n    set graining(v) {\r\n        this._graining = v;\r\n        this.redraw();\r\n    }\r\n\r\n    set random(v) {\r\n        this._random = v;\r\n        this.redraw();\r\n    }\r\n\r\n    setExtraAttribsInBuffer(operation) {\r\n        // Make sure that the noise texture is uploaded to the GPU.\r\n        this._noiseTexture.load();\r\n\r\n        let offset = operation.extraAttribsDataByteOffset / 4;\r\n        let floats = operation.quads.floats;\r\n\r\n        let length = operation.length;\r\n\r\n        for (let i = 0; i < length; i++) {\r\n\r\n            // Calculate noise texture coordinates so that it spans the full element.\r\n            let brx = operation.getElementWidth(i) / this._noiseTexture.getRenderWidth();\r\n            let bry = operation.getElementHeight(i) / this._noiseTexture.getRenderHeight();\r\n\r\n            let ulx = 0;\r\n            let uly = 0;\r\n            if (this._random) {\r\n                ulx = Math.random();\r\n                uly = Math.random();\r\n\r\n                brx += ulx;\r\n                bry += uly;\r\n\r\n                if (Math.random() < 0.5) {\r\n                    // Flip for more randomness.\r\n                    const t = ulx;\r\n                    ulx = brx;\r\n                    brx = t;\r\n                }\r\n\r\n                if (Math.random() < 0.5) {\r\n                    // Flip for more randomness.\r\n                    const t = uly;\r\n                    uly = bry;\r\n                    bry = t;\r\n                }\r\n            }\r\n\r\n            // Specify all corner points.\r\n            floats[offset] = ulx;\r\n            floats[offset + 1] = uly;\r\n\r\n            floats[offset + 2] = brx;\r\n            floats[offset + 3] = uly;\r\n\r\n            floats[offset + 4] = brx;\r\n            floats[offset + 5] = bry;\r\n\r\n            floats[offset + 6] = ulx;\r\n            floats[offset + 7] = bry;\r\n\r\n            offset += 8;\r\n        }\r\n    }\r\n\r\n    beforeDraw(operation) {\r\n        let gl = this.gl;\r\n        gl.vertexAttribPointer(this._attrib(\"aNoiseTextureCoord\"), 2, gl.FLOAT, false, 8, this.getVertexAttribPointerOffset(operation));\r\n\r\n        let glTexture = this._noiseTexture.source.nativeTexture;\r\n        gl.activeTexture(gl.TEXTURE1);\r\n        gl.bindTexture(gl.TEXTURE_2D, glTexture);\r\n        gl.activeTexture(gl.TEXTURE0);\r\n    }\r\n\r\n    getExtraAttribBytesPerVertex() {\r\n        return 8;\r\n    }\r\n\r\n    setupUniforms(operation) {\r\n        super.setupUniforms(operation);\r\n        this._setUniform(\"uNoiseSampler\", 1, this.gl.uniform1i);\r\n        this._setUniform(\"graining\", 2 * this._graining, this.gl.uniform1f);\r\n    }\r\n\r\n    enableAttribs() {\r\n        super.enableAttribs();\r\n        let gl = this.gl;\r\n        gl.enableVertexAttribArray(this._attrib(\"aNoiseTextureCoord\"));\r\n    }\r\n\r\n    disableAttribs() {\r\n        super.disableAttribs();\r\n        let gl = this.gl;\r\n        gl.disableVertexAttribArray(this._attrib(\"aNoiseTextureCoord\"));\r\n    }\r\n\r\n    useDefault() {\r\n        return this._graining === 0;\r\n    }\r\n\r\n    afterDraw(operation) {\r\n        if (this._random) {\r\n            this.redraw();\r\n        }\r\n    }\r\n\r\n}\r\n\r\nDitheringShader.vertexShaderSource = `\r\n    #ifdef GL_ES\r\n    # ifdef GL_FRAGMENT_PRECISION_HIGH\r\n    precision highp float;\r\n    # else\r\n    precision lowp float;\r\n    # endif\r\n    #endif\r\n    attribute vec2 aVertexPosition;\r\n    attribute vec2 aTextureCoord;\r\n    attribute vec2 aNoiseTextureCoord;\r\n    attribute vec4 aColor;\r\n    uniform vec2 projection;\r\n    varying vec2 vTextureCoord;\r\n    varying vec2 vNoiseTextureCoord;\r\n    varying vec4 vColor;\r\n    void main(void){\r\n        gl_Position = vec4(aVertexPosition.x * projection.x - 1.0, aVertexPosition.y * -abs(projection.y) + 1.0, 0.0, 1.0);\r\n        vTextureCoord = aTextureCoord;\r\n        vNoiseTextureCoord = aNoiseTextureCoord;\r\n        vColor = aColor;\r\n        gl_Position.y = -sign(projection.y) * gl_Position.y;\r\n    }\r\n`;\r\n\r\nDitheringShader.fragmentShaderSource = `\r\n    #ifdef GL_ES\r\n    # ifdef GL_FRAGMENT_PRECISION_HIGH\r\n    precision highp float;\r\n    # else\r\n    precision lowp float;\r\n    # endif\r\n    #endif\r\n    varying vec2 vTextureCoord;\r\n    varying vec2 vNoiseTextureCoord;\r\n    varying vec4 vColor;\r\n    uniform sampler2D uSampler;\r\n    uniform sampler2D uNoiseSampler;\r\n    uniform float graining;\r\n    void main(void){\r\n        vec4 noise = texture2D(uNoiseSampler, vNoiseTextureCoord);\r\n        vec4 color = texture2D(uSampler, vTextureCoord);\r\n        gl_FragColor = (color * vColor) + graining * (noise.r - 0.5);\r\n    }\r\n`;\r\n","/*\r\n * If not stated otherwise in this file or this component's LICENSE file the\r\n * following copyright and licenses apply:\r\n *\r\n * Copyright 2020 Metrological\r\n *\r\n * Licensed under the Apache License, Version 2.0 (the License);\r\n * you may not use this file except in compliance with the License.\r\n * You may obtain a copy of the License at\r\n *\r\n * http://www.apache.org/licenses/LICENSE-2.0\r\n *\r\n * Unless required by applicable law or agreed to in writing, software\r\n * distributed under the License is distributed on an \"AS IS\" BASIS,\r\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\r\n * See the License for the specific language governing permissions and\r\n * limitations under the License.\r\n */\r\n\r\nimport Utils from \"../../../tree/Utils.mjs\";\r\nimport DefaultShader from \"./DefaultShader.mjs\";\r\n\r\nexport default class CircularPushShader extends DefaultShader {\r\n\r\n    constructor(ctx) {\r\n        super(ctx);\r\n\r\n        this._inputValue = 0;\r\n\r\n        this._maxDerivative = 0.01;\r\n\r\n        this._normalizedValue = 0;\r\n\r\n        // The offset between buckets. A value between 0 and 1.\r\n        this._offset = 0;\r\n\r\n        this._amount = 0.1;\r\n\r\n        this._aspectRatio = 1;\r\n\r\n        this._offsetX = 0;\r\n\r\n        this._offsetY = 0;\r\n\r\n        this.buckets = 100;\r\n    }\r\n\r\n    get aspectRatio() {\r\n        return this._aspectRatio;\r\n    }\r\n\r\n    set aspectRatio(v) {\r\n        this._aspectRatio = v;\r\n        this.redraw();\r\n    }\r\n\r\n    get offsetX() {\r\n        return this._offsetX;\r\n    }\r\n\r\n    set offsetX(v) {\r\n        this._offsetX = v;\r\n        this.redraw();\r\n    }\r\n\r\n    get offsetY() {\r\n        return this._offsetY;\r\n    }\r\n\r\n    set offsetY(v) {\r\n        this._offsetY = v;\r\n        this.redraw();\r\n    }\r\n\r\n    set amount(v) {\r\n        this._amount = v;\r\n        this.redraw();\r\n    }\r\n\r\n    get amount() {\r\n        return this._amount;\r\n    }\r\n\r\n    set inputValue(v) {\r\n        this._inputValue = v;\r\n    }\r\n\r\n    get inputValue() {\r\n        return this._inputValue;\r\n    }\r\n\r\n    set maxDerivative(v) {\r\n        this._maxDerivative = v;\r\n    }\r\n\r\n    get maxDerivative() {\r\n        return this._maxDerivative;\r\n    }\r\n\r\n    set buckets(v) {\r\n        if (v > 100) {\r\n            console.warn(\"[Lightning] CircularPushShader: supports max 100 buckets\");\r\n            v = 100;\r\n        }\r\n\r\n        // This should be set before start