xy;\r\n    }\r\n`;\r\n\r\nRadialFilterShader.fragmentShaderSource = `\r\n    #ifdef GL_ES\r\n    # ifdef GL_FRAGMENT_PRECISION_HIGH\r\n    precision highp float;\r\n    # else\r\n    precision lowp float;\r\n    # endif\r\n    #endif\r\n    varying vec2 vTextureCoord;\r\n    varying vec2 pos;\r\n    varying vec4 vColor;\r\n    uniform sampler2D uSampler;\r\n    uniform float radius;\r\n    uniform float cutoff;\r\n    void main(void){\r\n        vec4 color = texture2D(uSampler, vTextureCoord);\r\n        float f = max(0.0, min(1.0, 1.0 - (length(pos) - radius) * cutoff));\r\n        gl_FragColor = texture2D(uSampler, vTextureCoord) * vColor * f;\r\n    }\r\n`;\r\n\r\n","/*\r\n * If not stated otherwise in this file or this component's LICENSE file the\r\n * following copyright and licenses apply:\r\n *\r\n * Copyright 2020 Metrological\r\n *\r\n * Licensed under the Apache License, Version 2.0 (the License);\r\n * you may not use this file except in compliance with the License.\r\n * You may obtain a copy of the License at\r\n *\r\n * http://www.apache.org/licenses/LICENSE-2.0\r\n *\r\n * Unless required by applicable law or agreed to in writing, software\r\n * distributed under the License is distributed on an \"AS IS\" BASIS,\r\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\r\n * See the License for the specific language governing permissions and\r\n * limitations under the License.\r\n */\r\n\r\nimport DefaultShader from \"./DefaultShader.mjs\";\r\nimport StageUtils from \"../../../tree/StageUtils.mjs\";\r\n\r\nexport default class RoundedRectangleShader extends DefaultShader {\r\n    constructor(context) {\r\n        super(context);\r\n        this._blend = 0;\r\n        this._radius = [1, 1, 1, 1];\r\n        this._stroke = 0;\r\n        this._fc = 0x00ffffff;\r\n        this._fillColor = this._getNormalizedColor(0xffffffff);\r\n        this._strokeColor = this._getNormalizedColor(0x00ffffff);\r\n    }\r\n\r\n    set blend(p) {\r\n        this._blend = Math.min(Math.max(p, 0), 1);\r\n    }\r\n\r\n    get blend() {\r\n        return this._blend;\r\n    }\r\n\r\n    set radius(v) {\r\n        if(Array.isArray(v)) {\r\n            if(v.length === 2) {\r\n                this._radius = [v[0], v[1], v[0], v[1]];\r\n            }\r\n            else if(v.length === 3) {\r\n                this._radius = [v[0], v[1], v[2], this._radius[3]];\r\n            }\r\n            else if (v.length === 4) {\r\n                this._radius = v;\r\n            }\r\n            else {\r\n                this._radius = [v[0], v[0], v[0], v[0]];\r\n            }\r\n        }\r\n        else {\r\n            this._radius = [v, v, v, v];\r\n        }\r\n        this.redraw();\r\n    }\r\n\r\n    get radius() {\r\n        return this._radius;\r\n    }\r\n\r\n    set topLeft(num) {\r\n        this._radius[0] = num;\r\n        this.redraw();\r\n    }\r\n\r\n    get topLeft() {\r\n        return this._radius[0];\r\n    }\r\n\r\n    set topRight(num) {\r\n        this._radius[1] = num;\r\n        this.redraw();\r\n    }\r\n\r\n    get topRight() {\r\n        return this._radius[1];\r\n    }\r\n\r\n    set bottomRight(num) {\r\n        this._radius[2] = num;\r\n        this.redraw();\r\n    }\r\n\r\n    get bottomRight() {\r\n        return this._radius[2];\r\n    }\r\n\r\n    set bottomLeft(num) {\r\n        this._radius[3] = num;\r\n        this.redraw();\r\n    }\r\n\r\n    get bottomLeft() {\r\n        return this._radius[3];\r\n    }\r\n\r\n    set strokeColor(argb) {\r\n        this._sc = argb;\r\n        this._strokeColor = this._getNormalizedColor(argb);\r\n        this.redraw();\r\n    }\r\n\r\n    get strokeColor() {\r\n        return this._sc;\r\n    }\r\n\r\n    set fillColor(argb) {\r\n        this._fc = argb;\r\n        this._fillColor = this._getNormalizedColor(argb);\r\n        this.redraw();\r\n    }\r\n\r\n    get fillColor() {\r\n        return this._fc;\r\n    }\r\n\r\n    set stroke(num) {\r\n       