calAlign === \"bottom\") {\r\n      offsetY += lineHeight - fontSize;\r\n    }\r\n\r\n    renderInfo.w = width;\r\n    renderInfo.h = height;\r\n    renderInfo.lines = lines;\r\n    renderInfo.precision = precision;\r\n\r\n    if (!width) {\r\n      // To prevent canvas errors.\r\n      width = 1;\r\n    }\r\n\r\n    if (!height) {\r\n      // To prevent canvas errors.\r\n      height = 1;\r\n    }\r\n\r\n    if (cutSx || cutEx) {\r\n      width = Math.min(width, cutEx - cutSx);\r\n    }\r\n\r\n    if (cutSy || cutEy) {\r\n      height = Math.min(height, cutEy - cutSy);\r\n    }\r\n\r\n    renderInfo.width = width;\r\n    renderInfo.innerWidth = innerWidth;\r\n    renderInfo.height = height;\r\n    renderInfo.fontSize = fontSize;\r\n    renderInfo.cutSx = cutSx;\r\n    renderInfo.cutSy = cutSy;\r\n    renderInfo.cutEx = cutEx;\r\n    renderInfo.cutEy = cutEy;\r\n    renderInfo.lineHeight = lineHeight;\r\n    renderInfo.lineWidths = lineWidths;\r\n    renderInfo.offsetY = offsetY;\r\n    renderInfo.paddingLeft = paddingLeft;\r\n    renderInfo.paddingRight = paddingRight;\r\n    renderInfo.letterSpacing = letterSpacing;\r\n    renderInfo.textIndent = textIndent;\r\n\r\n    return renderInfo as IRenderInfo;\r\n  }\r\n\r\n  _draw() {\r\n    const renderInfo = this._calculateRenderInfo();\r\n    const precision = renderInfo.precision;\r\n\r\n    // Add extra margin to prevent issue with clipped text when scaling.\r\n    this._canvas.width = Math.ceil(\r\n      renderInfo.width + this._stage.getOption(\"textRenderIssueMargin\")\r\n    );\r\n    this._canvas.height = Math.ceil(renderInfo.height);\r\n\r\n    // Canvas context has been reset.\r\n    this.setFontProperties();\r\n\r\n    if (renderInfo.fontSize >= 128) {\r\n      // WpeWebKit bug: must force compositing because cairo-traps-compositor will not work with text first.\r\n      this._context.globalAlpha = 0.01;\r\n      this._context.fillRect(0, 0, 0.01, 0.01);\r\n      this._context.globalAlpha = 1.0;\r\n    }\r\n\r\n    if (renderInfo.cutSx || renderInfo.cutSy) {\r\n      this._context.translate(-renderInfo.cutSx, -renderInfo.cutSy);\r\n    }\r\n\r\n    const rtl = this._settings.rtl;\r\n    let textAlign = this._settings.textAlign;\r\n    if (rtl) {\r\n      if (textAlign === \"left\") textAlign = \"right\";\r\n      else if (textAlign === \"right\") textAlign = \"left\";\r\n    }\r\n\r\n    const offsetY = renderInfo.offsetY;\r\n\r\n    let linePositionX;\r\n    let linePositionY;\r\n\r\n    const drawLines: IDrawLineInfo[] = [];\r\n\r\n    // Layout lines\r\n    for (let i = 0, n = renderInfo.lines.length; i < n; i++) {\r\n      const lineWidth = renderInfo.lineWidths[i] || 0;\r\n\r\n      linePositionX = rtl ? renderInfo.paddingRight : renderInfo.paddingLeft;\r\n      if (i === 0 && !rtl) {\r\n        linePositionX += renderInfo.textIndent;\r\n      }\r\n\r\n      if (textAlign === \"right\") {\r\n        linePositionX += renderInfo.innerWidth - lineWidth;\r\n      } else if (textAlign === \"center\") {\r\n        linePositionX += (renderInfo.innerWidth - lineWidth) / 2;\r\n      }\r\n\r\n      linePositionY = i * renderInfo.lineHeight + offsetY;\r\n\r\n      drawLines.push({\r\n        info: renderInfo.lines[i]!,\r\n        x: linePositionX,\r\n        y: linePositionY,\r\n        w: lineWidth,\r\n      });\r\n    }\r\n\r\n    if (this._settings.highlight) {\r\n      this._drawHighlight(precision, renderInfo, drawLines);\r\n    }\r\n\r\n    if (this._settings.shadow) {\r\n      this._drawShadow(precision);\r\n    }\r\n\r\n    this._drawLines(drawLines, renderInfo.letterSpacing);\r\n\r\n    if (this._settings.shadow) {\r\n      this._restoreShadow();\r\n    }\r\n\r\n    if (renderInfo.cutSx || renderInfo.cutSy) {\r\n      this._context.translate(renderInfo.cutSx, renderInfo.cutSy);\r\n    }\r\n\r\n    this.renderInfo = renderInfo;\r\n  }\r\n\r\n  protected _drawLines(drawLines: IDrawLineInfo[], letterSpacing: number) {\r\n    const ctx = this._context;\r\n    ctx.fillSt