lor;\r\n        \r\n        gl_Position.y = -sign(projection.y) * gl_Position.y;\r\n    }\r\n`;\r\n\r\nLight3dShader.fragmentShaderSource = `\r\n    #ifdef GL_ES\r\n    # ifdef GL_FRAGMENT_PRECISION_HIGH\r\n    precision highp float;\r\n    # else\r\n    precision lowp float;\r\n    # endif\r\n    #endif\r\n    varying vec2 vTextureCoord;\r\n    varying vec4 vColor;\r\n    varying vec3 pos;\r\n    uniform sampler2D uSampler;\r\n    uniform float ambient;\r\n    uniform float strength;\r\n    void main(void){\r\n        vec4 rgba = texture2D(uSampler, vTextureCoord);\r\n        float d = length(pos);\r\n        float n = 1.0 / max(0.1, d);\r\n        rgba.rgb = rgba.rgb * (strength * n + ambient);\r\n        gl_FragColor = rgba * vColor;\r\n    }\r\n`;\r\n\r\n","/*\r\n * If not stated otherwise in this file or this component's LICENSE file the\r\n * following copyright and licenses apply:\r\n *\r\n * Copyright 2020 Metrological\r\n *\r\n * Licensed under the Apache License, Version 2.0 (the License);\r\n * you may not use this file except in compliance with the License.\r\n * You may obtain a copy of the License at\r\n *\r\n * http://www.apache.org/licenses/LICENSE-2.0\r\n *\r\n * Unless required by applicable law or agreed to in writing, software\r\n * distributed under the License is distributed on an \"AS IS\" BASIS,\r\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\r\n * See the License for the specific language governing permissions and\r\n * limitations under the License.\r\n */\r\n\r\nimport DefaultShader from \"./DefaultShader.mjs\";\r\n\r\nexport default class PerspectiveShader extends DefaultShader {\r\n\r\n    constructor(ctx) {\r\n        super(ctx);\r\n\r\n        this._fudge = 0.2;\r\n        this._rx = 0;\r\n        this._ry = 0;\r\n        this._z = 1.0;\r\n    }\r\n\r\n    setupUniforms(operation) {\r\n        super.setupUniforms(operation);\r\n\r\n        const vr = operation.shaderOwner;\r\n        const element = vr.el